#!/usr/bin/env bash
# СУДИТ: hooks/five-whys-gate.sh
# probe_D513 — отказ стража разбора НЕ требует речи модели: текст отказа не просит произнести цепочку «почему».
# Это выжившая часть результата D513 (4 октября 2026: требование речи давало обрыв `reasoning_extraction` защитой API).
# Часть «три читающих вызова снимают отказ» отменена D1033 и заменена D1035 (снимает названный исход) — её судят
# probe_D1035 и test_five_whys_gate, здесь она не судится. Настоящий страж на фикстуре (рамка outcome_frame_lib.sh).
# Контроль: запись при поводе обязана быть отказана, иначе пробе нечего судить — 2. Красная — 1.
. "$(dirname "$0")/outcome_frame_lib.sh" || exit 2
P="$SB/p"; gproj "$P" || exit 2
TR="$SB/t.jsonl"; mk_tr "$TR" "Правлю строку."
touch "$ST/error_streak_fired_d513"
OUT=$(cw d513 "$P/hooks/x.sh" "$TR" "$P")
[ "$(dec "$OUT")" = deny ] || { echo "КОНТРОЛЬ: запись при поводе не отказана — пробе нечего судить" >&2; exit 2; }
WHY=$(jq -r '.hookSpecificOutput.permissionDecisionReason // ""' <<< "$OUT")
[ -n "$WHY" ] || exit 2
if grep -qE "произнес|цепочк[ауи] «почему»|звен|рассужден" <<< "$WHY"; then
    echo "КРАСНАЯ: текст отказа требует произнести цепочку (речь модели) — условие пропуска снова речь" >&2; exit 1
fi
echo "отказ есть, речи не требует"
exit 0
